* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #1c1c1c;
  background: #fdfbf6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.container {
  max-width: 660px;
  margin: 0 auto;
  padding: 30px 20px 40px;
}

header {
  margin-bottom: 25px;
}

.brand {
  font-size: 20px;
  font-weight: 500;
  margin: 0 0 22px 0;
  color: #1c1c1c;
  letter-spacing: -0.01em;
}

nav ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
}

nav a {
  text-decoration: none;
  color: #2a2a2a;
  font-size: 16px;
}

nav a:hover {
  color: #000;
}

.divider {
  border: none;
  border-top: 1px solid #d8d4c8;
  margin: 0;
}

main {
  padding: 50px 0 55px 0;
}

main h1 {
  font-size: 28px;
  font-weight: 600;
  margin: 0 0 32px 0;
  color: #1c1c1c;
  letter-spacing: -0.01em;
}

main p {
  margin: 0 0 16px 0;
  color: #1c1c1c;
}

main p:last-child {
  margin-bottom: 0;
}

ul.bullets {
  list-style: disc;
  padding-left: 22px;
  margin: 0;
}

ul.bullets li {
  margin-bottom: 8px;
  padding-left: 4px;
}

ul.bullets li:last-child {
  margin-bottom: 0;
}

footer {
  color: #9a9a9a;
  font-size: 14px;
  padding-top: 22px;
}

footer p {
  margin: 0;
}

@media (max-width: 768px) {
  .container {
    padding: 28px 20px 40px;
  }

  nav ul {
    gap: 18px;
  }

  main {
    padding: 42px 0 50px 0;
  }

  main h1 {
    font-size: 26px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 22px 20px 40px;
  }

  .brand {
    font-size: 19px;
    margin-bottom: 18px;
  }

  nav ul {
    gap: 16px;
  }

  nav a {
    font-size: 15px;
  }

  main {
    padding: 36px 0 45px 0;
  }

  main h1 {
    font-size: 24px;
    margin-bottom: 26px;
  }

  main p,
  ul.bullets li {
    font-size: 15px;
  }

  footer {
    font-size: 13px;
    padding-top: 18px;
  }
}

